      <Image
        accessible
        aria-hidden={ariaHidden}
        aria-label={
          ariaHidden ? 'This should be hidden' : 'This should be accessible'
        }
        source={require('../../assets/like.png')}
        style={styles.button}
      />
    </View>
  );
