component CompositeAnimationsWithEasingExample() {
  const anims = [1, 2, 3].map(() => new Animated.Value(0));
  const theme = useContext(RNTesterThemeContext);

  return (
    <View>
      <RNTConfigurationBlock>
        <Text style={{color: theme.SecondaryLabelColor}}>
          Note you cannot `useNativeDriver` for layout properties.
        </Text>
      </RNTConfigurationBlock>
      <RNTesterButton
        onPress={() => {
          Animated.sequence([
            // One after the other
            Animated.timing(anims[0], {
              toValue: 200,
              easing: Easing.linear,
              useNativeDriver: false,
            }),
            Animated.delay(400), // Use with sequence
            Animated.timing(anims[0], {
              toValue: 0,

              // Springy
              easing: Easing.elastic(2),

              useNativeDriver: false,
            }),
            Animated.delay(400),
            Animated.stagger(
              200,
              anims
                .map(anim =>
                  Animated.timing(anim, {
                    toValue: 200,
                    useNativeDriver: false,
                  }),
                )
                .concat(
                  anims.map(anim =>
                    Animated.timing(anim, {
                      toValue: 0,
                      useNativeDriver: false,
                    }),
                  ),
                ),
            ),
            Animated.delay(400),
            Animated.parallel(
              [
                Easing.inOut(Easing.quad), // Symmetric
                Easing.back(1.5), // Goes backwards first
                Easing.ease, // Default bezier
              ].map((easing, ii) =>
                Animated.timing(anims[ii], {
                  toValue: 320,
                  easing,
                  duration: 3000,
                  useNativeDriver: false,
                }),
              ),
            ),
            Animated.delay(400),
            Animated.stagger(
              200,
              anims.map(anim =>
                Animated.timing(anim, {
                  toValue: 0,

                  // Like a ball
                  easing: Easing.bounce,

                  duration: 2000,
                  useNativeDriver: false,
                }),
              ),
            ),
          ]).start();
        }}>
        Press to Animate
      </RNTesterButton>
      {['Composite', 'Easing', 'Animations!'].map((text, ii) => (
        <Animated.View
          key={text}
          style={[
            styles.content,
            {
              left: anims[ii],
            },
          ]}>
          <Text>{text}</Text>
        </Animated.View>
      ))}
    </View>
  );
}

