const colors = ['lime', 'green'];

function useLoop() {
  const animatedValue = useAnimatedValue(0);

  React.useEffect(() => {
    const animation = Animated.loop(
      Animated.sequence([
        Animated.timing(animatedValue, {
          toValue: 1,
          duration: 1000,
          useNativeDriver: true,
        }),
        Animated.timing(animatedValue, {
          toValue: 0,
          duration: 1000,
          useNativeDriver: true,
        }),
      ]),
    );
    animation.start();

    return () => {
      animation.stop();
    };
  }, [animatedValue]);

  return animatedValue;
}

const N = 12;
const STATE_MAX = 30;

function ChessboardExample() {
  const [state, setState] = React.useState(0);

  const animatedValue = useLoop();

  React.useEffect(() => {
    const id = setInterval(() => {
      setState(s => (s + 1) % STATE_MAX);
    }, 10);
    return () => {
      clearInterval(id);
    };
  }, []);

  const animatedStyle = useMemo(() => {
    return {
      width: animatedValue.interpolate({
        inputRange: [0, 1],
        outputRange: [10, 30],
      }),
      height: animatedValue.interpolate({
        inputRange: [0, 1],
        outputRange: [10, 30],
      }),
    };
  }, [animatedValue]);

  return (
    <View style={styles.workaround} collapsable={false}>
      <Text style={styles.text}>{state}</Text>
      <View style={styles.chessboard}>
        <View style={styles.border}>
          {[...Array(N).keys()].map(i => (
            <View style={styles.row} key={i}>
              {[...Array(N).keys()].map(j => (
                <Animated.View
                  key={j}
                  style={[
                    {
                      opacity: 0.3 + (state / STATE_MAX) * 0.7,
                      backgroundColor: colors[(i + j) % 2],
                    },
                    animatedStyle,
                  ]}
                />
              ))}
            </View>
          ))}
        </View>
      </View>
    </View>
  );
}

