  return (
    <View style={styles.tableRow}>
      <View style={styles.tableResultColumn}>
        <Text style={STATUS_TEXT_STYLE_MAPPING[testResult.status]}>
          {DISPLAY_STATUS_MAPPING[testResult.status]}
        </Text>
