              <Text style={styles.smallButtonTextLabel}>
                ScrollToOffset 500
              </Text>
            </TouchableOpacity>
          </View>
        </View>
        <View style={styles.smallButtonRow}>
          <View style={styles.smallButtonContainer}>
            <TouchableOpacity
              style={styles.smallButtonText}
              onPress={clearData}>
              <Text style={styles.smallButtonTextLabel}>
                Clear (empty list)
              </Text>
            </TouchableOpacity>
          </View>
          <View style={styles.smallButtonContainer}>
            <TouchableOpacity
