function roundRect(rect: unknown): ?{
  x: number,
  y: number,
  width: number,
  height: number,
} {
  if (rect == null || typeof rect !== 'object') {
    return null;
  }
  // $FlowFixMe[prop-missing]
  const x = rect.x;
  // $FlowFixMe[prop-missing]
  const y = rect.y;
  // $FlowFixMe[prop-missing]
  const width = rect.width;
  // $FlowFixMe[prop-missing]
  const height = rect.height;

  if (
    typeof x !== 'number' ||
    typeof y !== 'number' ||
    typeof width !== 'number' ||
    typeof height !== 'number'
  ) {
    return null;
  }
  return {
    x: Math.round(x),
    y: Math.round(y),
    width: Math.round(width),
    height: Math.round(height),
  };
}

/**
