function Comparison<ExpectedT, ActualT>({
  children,
  actual,
  expected,
}: {
  children: (value: ExpectedT | ActualT) => React.Node,
  actual: ActualT,
  expected: ExpectedT,
}): React.Node {
  return (
    <>
      <RNTesterText style={{fontWeight: 'bold'}}>Actual</RNTesterText>
      {children(actual)}
      <RNTesterText style={{fontWeight: 'bold'}}>Expected</RNTesterText>
      {children(expected)}
    </>
  );
}

