function TextAndLayoutLinesJSON({
  testID,
  ellipsizeMode,
}: Readonly<{
  testID: string,
  ellipsizeMode: 'head' | 'tail' | 'middle' | 'clip',
}>): React.Node {
  const [lines, setLines] = useState<?(TextLayoutLine[])>();

  return (
