      </RNTesterButton>
      <View testID="text-styles">
        {examples.map(({name, multiline, textStyles}) => (
          <WithLabel label={name} key={name}>
            {multiline ? (
              <MultilineStyledTextInput
                name={name}
                textStyles={textStyles}
                styleOffset={offset}
              />
