          </TouchableOpacity>
          <TouchableOpacity
            onPress={() => this.setState({testResults: {}})}
            style={[styles.column, styles.button]}>
            <RNTesterText style={styles.buttonTextLarge}>
              Clear results
            </RNTesterText>
          </TouchableOpacity>
        </View>
        <FlatList
          // $FlowFixMe[incompatible-type]
          data={Object.keys(this._tests)}
          keyExtractor={item => item}
          renderItem={({item}: {item: Examples, ...}) => (
            <View style={styles.item}>
              <TouchableOpacity
                style={[styles.column, styles.button]}
                onPress={e => this._setResult(item, this._tests[item]())}>
                <RNTesterText style={styles.buttonText}>{item}</RNTesterText>
              </TouchableOpacity>
              <View style={[styles.column]}>{this._renderResult(item)}</View>
            </View>
          )}
        />
        {Platform.OS === 'android' && (
          <>
            <View style={styles.item}>
              <RNTesterText style={styles.buttonTextLarge}>
                Activity result tests (Android)
              </RNTesterText>
            </View>
            <FlatList
              // $FlowFixMe[incompatible-type]
              data={Object.keys(this._androidTests)}
              keyExtractor={item => item}
              renderItem={({item}: {item: AndroidExamples, ...}) => (
                <View style={styles.item}>
                  <TouchableOpacity
                    style={[styles.column, styles.button]}
                    onPress={e => this._androidTests[item]()}>
                    <RNTesterText style={styles.buttonText}>
                      {item}
                    </RNTesterText>
                  </TouchableOpacity>
                  <View style={[styles.column]}>
                    {/* $FlowFixMe[incompatible-type] */}
                    {this._renderResult(item)}
                  </View>
                </View>
              )}
            />
          </>
        )}
        <View style={styles.item}>
          <RNTesterText style={styles.buttonTextLarge}>
            Report errors tests
          </RNTesterText>
        </View>
        <FlatList
          // $FlowFixMe[incompatible-type]
          data={Object.keys(this._errorTests)}
          keyExtractor={item => item}
          renderItem={({item}: {item: ErrorExamples, ...}) => (
            <View style={styles.item}>
              <TouchableOpacity
                style={[styles.column, styles.button]}
